def visual(n,vis,m):
 if n in (48,50,51,52):
  vis["threeDRequirements"]["trajectory"].update(enabled=n in (50,51,52),kind="optimization_iterates" if n==52 else "single_update" if n in (50,51) else "none")
  vis["twoDRequirements"]["relationshipTo3D"]="Stesso costo, stessa regione e stessi punti; in 3D la regione limita la parte ammissibile della superficie."
 if n==53:
  vis["threeDRequirements"]["trajectory"].update(enabled=False,kind="none")
  vis["visualizationSemantics"]["explanation"]="d=1: curva; d=2: livelli e superficie del costo selezionato. Nessuna dimensione fisica aggiunta."
  vis["twoDRequirements"]["plotType"]="selected_cost_curve_or_contour"
 if n==49:
  vis["visualizationSemantics"]["xAxis"].update(label="z₁",symbol="z₁",role="decision")
  vis["visualizationSemantics"]["yAxis"].update(label="z₂",symbol="z₂",role="decision")
  vis["twoDRequirements"]["plotType"]="projection_geometry"
 if n==54:
  vis["visualizationSemantics"]["yAxis"].update(label="Costo e barriera",symbol="ℓ / Fε / Bε",role="cost")
  vis["twoDRequirements"]["plotType"]="barrier_profiles"
